function pc_out(array $d,int $s=200):never{http_response_code($s);echo json_encode($d,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);exit;}
function pc_can_write(array $u):bool{if(($u['role']??'')==='Super Admin')return true;$p=$u['permissions']['Accounts']??null;if($p==='all')return true;if(!is_array($p))return false;if(in_array('Create',$p,true)||in_array('Edit',$p,true)||in_array('Approve',$p,true))return true;foreach($p as $a)if(is_array($a)&&(in_array('Create',$a,true)||in_array('Edit',$a,true)||in_array('Approve',$a,true)))return true;return false;}
function pc_accounts_default():array{return ['revision'=>0,'journals'=>[],'events'=>[],'commodityBills'=>[],'inventoryCostRates'=>[],'localSalesCostRates'=>[],'productionCostRuns'=>[]];}
function pc_read_accounts():array{tt_ensure_data_dir();if(!is_file(TT_PC_ACCOUNTS))return pc_accounts_default();$h=fopen(TT_PC_ACCOUNTS,'r');if($h===false||!flock($h,LOCK_SH))throw new RuntimeException('Accounts storage unavailable.');try{$raw=stream_get_contents($h);}finally{flock($h,LOCK_UN);fclose($h);} $v=$raw?json_decode($raw,true):null;return is_array($v)?array_replace_recursive(pc_accounts_default(),$v):pc_accounts_default();}
function pc_read_operations():array{if(!is_file(TT_PC_OPERATIONS))return ['values'=>[]];$h=fopen(TT_PC_OPERATIONS,'r');if($h===false||!flock($h,LOCK_SH))throw new RuntimeException('Operational storage unavailable.');try{$raw=stream_get_contents($h);}finally{flock($h,LOCK_UN);fclose($h);} $v=$raw?json_decode($raw,true):null;return is_array($v)?$v:['values'=>[]];}
function pc_op(array $ops,string $key):array{$raw=$ops['values'][$key]??'';if(!is_string($raw)||$raw==='')return [];$v=json_decode($raw,true);return is_array($v)?$v:[];}
function pc_date(string $v):string{if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$v))pc_out(['ok'=>false,'error'=>'Valid date required.'],422);return $v;}
function pc_entity(string $v):string{$v=strtoupper(trim($v));if(!in_array($v,['TTI','BRM'],true))pc_out(['ok'=>false,'error'=>'Production costing is available for TTI / BRM Pakistan books.'],422);return $v;}
function pc_norm(string $v):string{return strtoupper(trim(preg_replace('/\s+/',' ',preg_replace('/[^A-Z0-9]+/i',' ',trim($v))??trim($v))??trim($v)));}
function pc_variety_key(string $v):string{$u=pc_norm($v);$base='';if(str_contains($u,'IRRI 6'))$base='IRRI-6';elseif(str_contains($u,'1121'))$base='1121';elseif(str_contains($u,'PK 386'))$base='PK-386';elseif(str_contains($u,'SUPER KERNEL'))$base='SUPER KERNEL';elseif(str_contains($u,'D 98'))$base='D-98';elseif(preg_match('/(^| )C 9( |$)/',$u))$base='C-9';else $base=$u?:'RICE';if(str_contains($u,'PARBOIL'))$base.=' PARBOIL';return $base;}
function pc_product_key(string $v):string{$u=pc_norm($v);if(str_starts_with($u,'B2 CSR'))return 'B2 CSR';if(str_starts_with($u,'B2')||str_contains($u,'BROKEN B2'))return 'B2';if($u==='CSR')return 'CSR';if($u==='B3')return 'B3';if($u==='PADDY')return 'PADDY';if($u==='POWDER')return 'POWDER';return $u;}
function pc_is_waste(string $v):bool{$u=pc_norm($v);return str_contains($u,'STONE')||str_contains($u,'SUTLI')||str_contains($u,'DUST');}
function pc_next(array $items,string $p):string{$n=count($items)+1;do{$id=$p.'-'.gmdate('Y').'-'.str_pad((string)$n,6,'0',STR_PAD_LEFT);$n++;}while(isset($items[$id]));return $id;}
function pc_rates(array $s):array{$rows=[];foreach((array)($s['localSalesCostRates']??[]) as $r)if(is_array($r))$rows[]=$r;foreach((array)($s['inventoryCostRates']??[]) as $r)if(is_array($r))$rows[]=$r;return $rows;}
function pc_rate_for(array $s,string $entity,string $product,string $date):?array{$best=null;$pk=pc_product_key($product);foreach(pc_rates($s) as $r){if(($r['status']??'Active')!=='Active'||($r['entity']??'')!==$entity)continue;$matches=pc_product_key((string)($r['product']??''))===$pk;if(!$matches)foreach((array)($r['aliases']??[]) as $a)if(pc_product_key((string)$a)===$pk){$matches=true;break;}if(!$matches)continue;$from=(string)($r['effectiveFrom']??'');if($from===''||$from>$date)continue;if($best===null||$from>(string)($best['effectiveFrom']??''))$best=$r;}return $best;}
function pc_bill_values(array $s):array{$out=[];foreach((array)($s['commodityBills']??[]) as $b){if(!is_array($b)||($b['status']??'')!=='Verified / Posted')continue;$alloc=(array)($b['receiptAllocations']??[]);$base=0.0;foreach($alloc as $a)$base+=max(0,(float)($a['provisionalAmount']??0));$total=round((float)($b['finalCommodityValue']??0)+(float)($b['brokerageGross']??0),2);if($total<=0||!$alloc)continue;$count=count($alloc);$used=0.0;foreach($alloc as $i=>$a){$key=(string)($a['sourceKey']??'');if($key==='')continue;$part=$i===$count-1?round($total-$used,2):round($total*($base>0?max(0,(float)($a['provisionalAmount']??0))/$base:1/$count),2);$used=round($used+$part,2);$out[$key]=['value'=>$part,'billId'=>(string)($b['id']??''),'final'=>true];}}return $out;}
function pc_receipts(array $s):array{$bill=pc_bill_values($s);$out=[];foreach((array)($s['events']??[]) as $e){if(!is_array($e)||($e['eventType']??'')!=='COMMODITY_RECEIPT_ACCEPTED')continue;$jid=(string)($e['journalId']??'');$j=$s['journals'][$jid]??null;if(!is_array($j))continue;$m=is_array($j['meta']??null)?$j['meta']:[];$kg=(float)($m['payableWeightKg']??0);if($kg<=0)continue;$key=(string)($e['sourceKey']??'');$b=$bill[$key]??null;$out[]=['entity'=>(string)($e['entity']??$j['entity']??'TTI'),'date'=>(string)($j['date']??''),'sourceKey'=>$key,'variety'=>(string)($m['variety']??''),'varietyKey'=>pc_variety_key((string)($m['variety']??'')),'kg'=>$kg,'value'=>$b?(float)$b['value']:(float)($j['totalDebit']??0),'final'=>$b!==null,'billId'=>$b['billId']??''];}usort($out,static fn($a,$b)=>strcmp((string)$a['date'],(string)$b['date']));return $out;}
function pc_production(array $ops):array{$rows=[];foreach(pc_op($ops,'tt30prod') as $p){if(!is_array($p))continue;$date=(string)($p['date']??'');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))continue;$outs=[];$input=0.0;$ready=0.0;foreach((array)($p['rows']??[]) as $r){if(!is_array($r)||(!empty($r['systemFixed'])&&!empty($r['noStockPost'])))continue;$kg=(float)($r['systemKg']??0);if($kg<=0)$kg=(float)($r['bags']??0)*(float)($r['bagWeight']??0);if($kg<=0)continue;$name=trim((string)($r['product']??'Unknown'));$isReady=str_starts_with(strtoupper($name),'READY RICE');$outs[]=['product'=>$name,'kg'=>round($kg,3),'ready'=>$isReady];$input+=$kg;if($isReady)$ready+=$kg;}if($input<=0)continue;$rows[]=['id'=>(string)($p['id']??($date.'|'.($p['shift']??'').'-'.count($rows))),'date'=>$date,'shift'=>(string)($p['shift']??''),'variety'=>(string)($p['variety']??'Rice'),'varietyKey'=>pc_variety_key((string)($p['variety']??'Rice')),'inputKg'=>round($input,3),'readyKg'=>round($ready,3),'outputs'=>$outs];}usort($rows,static fn($a,$b)=>strcmp((string)$a['date'],(string)$b['date'])?:strcmp((string)$a['shift'],(string)$b['shift']));return $rows;}
function pc_group_production(array $prod):array{$g=[];foreach($prod as $p){$id=$p['date'].'|'.$p['varietyKey'];if(!isset($g[$id]))$g[$id]=['id'=>$id,'date'=>$p['date'],'variety'=>$p['variety'],'varietyKey'=>$p['varietyKey'],'inputKg'=>0.0,'readyKg'=>0.0,'outputs'=>[],'runIds'=>[]];$g[$id]['inputKg']+=$p['inputKg'];$g[$id]['readyKg']+=$p['readyKg'];$g[$id]['runIds'][]=$p['id'];foreach($p['outputs'] as $o){$k=$o['product'];if(!isset($g[$id]['outputs'][$k]))$g[$id]['outputs'][$k]=['product'=>$k,'kg'=>0.0,'ready'=>$o['ready']];$g[$id]['outputs'][$k]['kg']+=$o['kg'];}}foreach($g as &$x){$x['inputKg']=round($x['inputKg'],3);$x['readyKg']=round($x['readyKg'],3);$x['outputs']=array_values($x['outputs']);foreach($x['outputs'] as &$o)$o['kg']=round($o['kg'],3);unset($o);}unset($x);uasort($g,static fn($a,$b)=>strcmp((string)$a['date'],(string)$b['date'])?:strcmp((string)$a['varietyKey'],(string)$b['varietyKey']));return $g;}
function pc_cost_sources(array $ops,array $groups):array{$src=[];$add=function(string $id,string $type,string $from,string $to,float $amount,string $ref='')use(&$src,$groups){if($amount<=0||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$from)||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$to))return;$kg=0.0;foreach($groups as $g)if($g['date']>=$from&&$g['date']<=$to)$kg+=(float)$g['inputKg'];if($kg<=0)return;$src[]=['id'=>$id,'type'=>$type,'from'=>$from,'to'=>$to,'amount'=>round($amount,2),'productionKg'=>round($kg,3),'ratePerKg'=>$amount/$kg,'reference'=>$ref];};foreach(pc_op($ops,'tt38kebills') as $x)if(is_array($x))$add('KE|'.($x['id']??$x['ref']??count($src)),'Electricity',(string)($x['readFrom']??$x['date']??''),(string)($x['readTo']??$x['date']??''),(float)($x['amount']??0),(string)($x['ref']??''));foreach(pc_op($ops,'tt38labourbills') as $x)if(is_array($x))$add('LAB|'.($x['id']??$x['billNo']??count($src)),'Labour',(string)($x['from']??$x['date']??''),(string)($x['till']??$x['date']??''),(float)($x['amount']??0),(string)($x['billNo']??$x['ref']??''));foreach(pc_op($ops,'tt37processingexpenses') as $x)if(is_array($x)){$d=(string)($x['date']??'');$add('EXP|'.($x['id']??$x['ref']??count($src)),(string)($x['type']??'Processing Expense'),$d,$d,(float)($x['amount']??0),(string)($x['ref']??''));}return $src;}
